#include "physics/NativeGameClutchV186.h"
#include <iostream>
#include <cstring>
namespace G=motorrock::gameangularv113;namespace P=motorrock::nativepublicangular;
static float value(unsigned u){float v;std::memcpy(&v,&u,4);return v;}
static unsigned word(float v){unsigned u;std::memcpy(&u,&v,4);return u;}
template<class T>static void emit(const T&a){std::cout<<'[';for(unsigned i=0;i<a.size();++i){if(i)std::cout<<',';std::cout<<word(a[i]);}std::cout<<']';}
int main(){unsigned c,u;while(std::cin>>c){G::Quaternion q;G::Vector inv,omega,damp;for(auto&v:q){std::cin>>u;v=value(u);}for(auto&v:inv){std::cin>>u;v=value(u);}for(auto&v:omega){std::cin>>u;v=value(u);}for(auto&v:damp){std::cin>>u;v=value(u);}unsigned roll,pitch,contact;unsigned clutch,strength,mass;std::cin>>roll>>pitch>>contact>>clutch>>strength>>mass;auto m=motorrock::stabilizev186::stabilize(q,inv,omega,damp,value(roll),value(pitch),contact!=0,clutch!=0,value(strength),value(mass));G::Vector euler{};if(value(roll)>0||value(pitch)>0)q=motorrock::stabilizev185::clampOrientation(q,value(roll),value(pitch),&euler);auto v=G::velocity(G::inverseTensor(q,inv),m);G::Vector inertia;for(unsigned i=0;i<3;++i)inertia[i]=motorrock::contactframe::store(1.0/inv[i]);auto mat=P::orientation(q);auto before=P::momentum(P::inertia(mat,inertia),omega);auto inverse=motorrock::stabilizev185::inverse(mat);auto local=motorrock::stabilizev185::product(inverse,before);std::array<float,9>matflat{},invflat{};for(unsigned i=0;i<3;++i)for(unsigned j=0;j<3;++j){matflat[i*3+j]=mat[i][j];invflat[i*3+j]=inverse[i][j];}std::cout<<"{\"case\":"<<c<<",\"matrix\":";emit(matflat);std::cout<<",\"inverse\":";emit(invflat);std::cout<<",\"momentum_before\":";emit(before);std::cout<<",\"local\":";emit(local);std::cout<<",\"momentum\":";emit(m);std::cout<<",\"omega_after\":";emit(v);std::cout<<",\"rotation_after\":";emit(q);std::cout<<",\"euler\":";emit(euler);std::cout<<"}\n";}return 0;}
